declare
  n integer;
  hors integer;
begin
  select count(*) into n from public.texte_note_renvois where metadata->>'mission' = $r$A0044|renvois-notes-stables-20260916$r$;
  if n <> 60 then raise exception 'renvois A0044 : attendu 60 relations, trouvé %', n; end if;
  select count(*) into hors from public.texte_note_renvois r
   where not exists (select 1 from public.texte_notes t where t.id_texte = r.target_id_texte and t.note_key = r.target_note_key)
      or strpos((select b.text from public.texte_note_blocs b where b.id_texte = r.source_id_texte and b.note_key = r.source_note_key and b.block_id = r.source_block_id), r.source_citation) = 0;
  if hors <> 0 then raise exception 'renvois A0044 : % relation(s) hors contrat', hors; end if;
end
$controle$;
